sql-chinook-monthly-running-total-revenu.starter_code:
WITH monthly AS (
  SELECT strftime('%Y-%m', InvoiceDate) AS Month,
         ROUND(SUM(Total), 2) AS MonthlyRevenue
  FROM Invoice
  GROUP BY strftime('%Y-%m', InvoiceDate)
)
SELECT Month, MonthlyRevenue,
       /* running total via SUM() OVER (ORDER BY Month ...) */ AS RunningTotal
FROM monthly
ORDER BY Month ASC;

